// Some portions generated by Codex

const test = require('node:test');
const assert = require('node:assert/strict');
const { MemoryWorker, loadApi } = require('./query-load-more-harness.js');

// A turn drains all runnable promise work. Worker gates, not elapsed time, determine progress.
const turn = () => new Promise(resolve => setImmediate(resolve));

function controlledApi(overrides = {}) {
    const timers = new Map();
    let nextTimer = 0;
    const loaded = loadApi({
        setTimeout(callback) { const id = ++nextTimer; timers.set(id, callback); return id; },
        clearTimeout(id) { timers.delete(id); },
        ...overrides
    });
    return { ...loaded, timers };
}

class GatedWorker extends MemoryWorker {
    constructor() {
        super();
        this.received = [];
        this.gates = new Set(['create']);
        this.waiting = [];
    }

    postMessage(message) {
        this.received.push(message);
        if (this.gates.has(message.op)) this.waiting.push(message);
        else super.postMessage(message);
    }

    open(op) {
        this.gates.delete(op);
        const ready = this.waiting.filter(message => message.op === op);
        this.waiting = this.waiting.filter(message => message.op !== op);
        for (const message of ready) super.postMessage(message);
    }
}

function observedBudget(api, maxBytes) {
    const budget = api.createRowStoreBudget(maxBytes);
    const reservations = [];
    const requests = [];
    let peakBytes = 0;
    let peakRetained = 0;
    function check() {
        const retained = reservations.filter(entry => entry.category === 'retained')
            .reduce((sum, entry) => sum + entry.reservation.bytes, 0);
        const accounted = reservations.reduce((sum, entry) => sum + entry.reservation.bytes, 0);
        assert.equal(accounted, budget.usedBytes, 'every live allocation has exactly one owner');
        assert.ok(retained <= maxBytes - Math.min(Math.floor(maxBytes / 2), 32 * 1024 * 1024),
            'retained allocations preserve the temporary write reserve');
        assert.ok(accounted <= maxBytes, 'total allocations never exceed the shared memory limit');
        peakBytes = Math.max(peakBytes, accounted);
        peakRetained = Math.max(peakRetained, retained);
    }
    return {
        get maxBytes() { return budget.maxBytes; },
        get usedBytes() { return budget.usedBytes; },
        get peakBytes() { return peakBytes; },
        get peakRetained() { return peakRetained; },
        get retainedBytes() {
            return reservations.filter(entry => entry.category === 'retained')
                .reduce((sum, entry) => sum + entry.reservation.bytes, 0);
        },
        requests,
        check,
        createReservation(category = 'retained') {
            const reservation = budget.createReservation(category);
            reservations.push({ category, reservation });
            return {
                get bytes() { return reservation.bytes; },
                grow(bytes, timeout) {
                    const request = { category, bytes, settled: false };
                    requests.push(request);
                    const growing = reservation.grow(bytes, timeout);
                    check();
                    return growing.then(() => { request.settled = true; check(); }, error => {
                        request.settled = true;
                        check();
                        throw error;
                    });
                },
                shrink(bytes) { reservation.shrink(bytes); check(); },
                release() { reservation.release(); check(); }
            };
        },
        registerPressureHandler(handler, onError) { return budget.registerPressureHandler(handler, onError); }
    };
}

test('four saturated stores spill ordinary input batches without new retained allocations', async () => {
    const { api } = controlledApi();
    const row = [{ kind: 'iri', value: 'urn:x' }];
    const budget = observedBudget(api, 2 * 4 * 2000 * api.estimateRowBytes(row));
    const workers = [];
    const stores = await Promise.all(Array.from({ length: 4 }, () => api.createRowStore({
        memoryBudget: budget, spillRowLimit: 0,
        workerFactory() { const worker = new GatedWorker(); workers.push(worker); return worker; }
    })));
    const producers = stores.map(async store => {
        for (let batch = 0; batch < 8; batch++) await store.append(Array.from({ length: 250 }, () => row));
    });
    // Install rejection handlers before exercising disposal on the failing implementation.
    const finished = Promise.allSettled(producers);
    try {
        await turn();
        assert.equal(workers.length, 4, 'all streams started a spill while their source rows accumulated');
        assert.ok(budget.peakRetained > budget.maxBytes * 0.4, 'the streams saturate retained admission');
        for (const worker of workers) worker.open('create');
        await turn();
        assert.ok(workers.every(worker => worker.received.some(message => message.op === 'append')),
            'every healthy worker must start writing even when source rows fill retained memory');
        assert.deepEqual(await finished, Array.from({ length: 4 }, () => ({ status: 'fulfilled', value: undefined })));
        assert.ok(stores.every(store => !store.inMemory), 'all stores finish spilling without a timeout or retry');
        assert.equal(workers.length, 4, 'healthy stores do not fall back or retry');
        for (let index = 0; index < stores.length; index++) {
            assert.equal(await stores[index].count(), 2000);
            assert.deepEqual(workers[index].rows, Array.from({ length: 2000 }, () => row));
            assert.equal((await stores[index].read(1999, 1))[0][0].value, 'urn:x');
        }
        budget.check();
    } finally {
        await Promise.all(stores.map(store => store.dispose()));
        await finished;
        assert.equal(budget.usedBytes, 0, 'cleanup releases metadata, source rows and pending reservations');
    }
});

function rows(count, prefix = 'urn:row:') {
    return Array.from({ length: count }, (_, index) => [{ kind: 'iri', value: prefix + index }]);
}

function metadataBytes(batches) {
    return batches.reduce((sum, batch) => sum + batch.length * 16 + (batch.length ? 160 : 0), 0);
}

async function assertRows(store, expected) {
    assert.equal(await store.count(), expected.length);
    for (let start = 0; start < expected.length; start += 100) {
        const window = await store.readOwned(start, Math.min(100, expected.length - start));
        assert.deepEqual(JSON.parse(JSON.stringify(window.rows)), expected.slice(start, start + 100));
        window.release();
    }
}

test('admitted metadata follows input arrays rather than spill chunks and later stored writes', async () => {
    const { api } = controlledApi();
    const budget = observedBudget(api, 4 * 1024 * 1024);
    const worker = new GatedWorker();
    const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0, workerFactory: () => worker });
    const blocker = budget.createReservation('retained');
    const retainedBlocker = budget.createReservation('retained');
    const input = [rows(2345, 'urn:first:'), rows(3001, 'urn:second:'), rows(17, 'urn:third:')];
    try {
        for (const batch of input) await store.append(batch);
        await blocker.grow(budget.maxBytes / 2 - budget.usedBytes);
        worker.open('create');
        await turn();
        assert.equal(store.inMemory, false, 'different input and copy boundaries still allow a saturated spill');
        assert.deepEqual(worker.received.filter(message => message.op === 'append').map(message => message.rowCount),
            [5000, 363]);
        assert.equal(budget.usedBytes, blocker.bytes + metadataBytes(input),
            'only the original admitted backing arrays remain, not arrays for each worker message');
        blocker.release();
        await assertRows(store, input.flat());

        worker.gates.add('append');
        const later = [rows(19, 'urn:later:'), rows(237, 'urn:queued:'), rows(7, 'urn:last:')];
        for (const batch of later) await store.append(batch);
        // The first write's temporary reservation is also live, so count retained bytes explicitly here.
        const temporary = budget.requests.filter(request => request.category === 'temporary').at(-1).bytes;
        await retainedBlocker.grow(budget.maxBytes / 2 - (budget.usedBytes - temporary));
        const retainedRequests = budget.requests.filter(request => request.category === 'retained').length;
        worker.open('append');
        await turn();
        assert.equal(budget.requests.filter(request => request.category === 'retained').length, retainedRequests,
            'already-spilled stores consume admitted metadata without another retained allocation');
        assert.equal(budget.usedBytes, retainedBlocker.bytes + metadataBytes(input.concat(later)));
        retainedBlocker.release();
        await assertRows(store, input.concat(later).flat());

        const beforePartial = budget.usedBytes;
        await store.truncate(1000);
        assert.equal(budget.usedBytes, metadataBytes([input[0]]),
            'a partially retained backing array stays fully charged');
        assert.ok(budget.usedBytes < beforePartial, 'fully removed arrays release their charges');
        await assertRows(store, input[0].slice(0, 1000));
        await store.truncate(0);
        assert.equal(budget.usedBytes, 0, 'truncating all stored rows releases the final backing array');
    } finally {
        blocker.release();
        retainedBlocker.release();
        await store.dispose();
        assert.equal(budget.usedBytes, 0);
    }
});

class FailingGatedWorker extends GatedWorker {
    fail(op) {
        const index = this.waiting.findIndex(message => message.op === op);
        assert.notEqual(index, -1, 'the operation to fail is held at its worker gate');
        const [message] = this.waiting.splice(index, 1);
        queueMicrotask(() => {
            const response = { requestId: message.requestId, ok: false, error: 'controlled storage failure' };
            for (const listener of this.listeners.get('message') || []) listener({ data: response });
        });
    }
}

for (const failRetry of [false, true]) {
    const outcome = failRetry ? 'and retry preserve readable fallback rows'
        : 'retries with the original metadata capacity';
    test(`a failed spill ${outcome}`,
        async () => {
            const { api } = controlledApi();
            const budget = observedBudget(api, 2 * 1024 * 1024);
            const workers = [];
            const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0, workerFactory() {
                const worker = new FailingGatedWorker();
                worker.gates.add('append');
                workers.push(worker);
                return worker;
            } });
            const input = [rows(701, 'urn:first:'), rows(1333, 'urn:second:')];
            const blocker = budget.createReservation('retained');
            try {
                for (const batch of input) await store.append(batch);
                const admitted = budget.usedBytes;
                await blocker.grow(budget.maxBytes / 2 - admitted);
                const retainedRequests = budget.requests.filter(request => request.category === 'retained').length;
                workers[0].open('create');
                await turn();
                workers[0].fail('append');
                await turn();
                assert.equal(workers.length, 2, 'one failed attempt creates exactly one replacement');
                assert.equal(workers[0].terminated, true);
                assert.equal(budget.usedBytes, admitted + blocker.bytes,
                    'the old attempt releases temporary bytes without releasing or duplicating admitted metadata');
                workers[1].open('create');
                await turn();
                if (failRetry) workers[1].fail('append');
                else workers[1].open('append');
                await turn();
                const finalRetainedRequests = budget.requests.filter(request => request.category === 'retained').length;
                assert.equal(finalRetainedRequests, retainedRequests,
                    'neither attempt requests new retained capacity');
                assert.equal(store.inMemory, failRetry);
                assert.equal(workers.length, 2);
                assert.equal(budget.usedBytes, blocker.bytes + (failRetry ? admitted : metadataBytes(input)));
                blocker.release();
                await assertRows(store, input.flat());
            } finally {
                blocker.release();
                await store.dispose();
                assert.equal(budget.usedBytes, 0);
            }
        });
}

for (const waitingForTransfer of [false, true]) {
    const phase = waitingForTransfer ? 'before encoding' : 'during a copy';
    test(`truncation ${phase} pins detached metadata until old writes finish`,
        async () => {
            const { api } = controlledApi();
            const budget = observedBudget(api, 2 * 1024 * 1024);
            const worker = new GatedWorker();
            worker.gates.add('append');
            const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0,
                workerFactory: () => worker });
            const input = [rows(331, 'urn:old:first:'), rows(673, 'urn:old:second:')];
            const replacement = rows(109, 'urn:new:' + '\u0000\ud800😀'.repeat(4));
            const blocker = budget.createReservation('temporary');
            try {
                for (const batch of input) await store.append(batch);
                if (waitingForTransfer) await blocker.grow(budget.maxBytes - budget.usedBytes);
                worker.open('create');
                await turn();
                assert.equal(worker.received.some(message => message.op === 'append'), !waitingForTransfer);
                const beforeTruncate = budget.usedBytes;
                await store.truncate(0);
                assert.equal(budget.usedBytes, beforeTruncate,
                    'a pending old write still owns both its captured source rows and detached metadata');
                let replacementAccepted = false;
                const appending = store.append(replacement).then(() => { replacementAccepted = true; });
                if (waitingForTransfer) {
                    await turn();
                    assert.equal(replacementAccepted, false,
                        'captured source rows cannot supply admission space while their copy is still blocked');
                }
                blocker.release();
                await appending;
                worker.open('append');
                await turn();
                assert.equal(store.inMemory, false);
                assert.match(worker.received.find(message => message.op === 'append').text, /urn:old:first:0/,
                    'the old source objects were still needed to encode the pending copy');
                assert.deepEqual(worker.rows, replacement,
                    'the stale copy is truncated before replacement rows are written');
                assert.equal(budget.usedBytes, metadataBytes([replacement]),
                    'old arrays are reclaimed once their writer ends');
                await assertRows(store, replacement);
            } finally {
                blocker.release();
                await store.dispose();
                assert.equal(budget.usedBytes, 0);
            }
        });
}

