test('disposal cancels source admission and metadata writers waiting for temporary memory', async () => {
    const { api } = controlledApi();
    const budget = observedBudget(api, 200000);
    const worker = new GatedWorker();
    const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0, workerFactory: () => worker });
    const blocker = budget.createReservation('temporary');
    await store.append(rows(500));
    await blocker.grow(budget.maxBytes - budget.usedBytes);
    worker.open('create');
    await turn();
    assert.equal(worker.received.some(message => message.op === 'append'), false, 'the write waits before encoding');
    const pending = store.append(rows(250, 'urn:waiting:'));
    const rejected = assert.rejects(pending, /released|disposed|closed/i);
    await turn();
    assert.ok(budget.requests.some(request => request.category === 'retained' && !request.settled));
    assert.ok(budget.requests.some(request => request.category === 'temporary' && !request.settled));
    await store.dispose();
    await rejected;
    assert.equal(worker.terminated, true);
    assert.equal(budget.usedBytes, blocker.bytes, 'only the independent temporary blocker survives disposal');
    blocker.release();
    assert.equal(budget.usedBytes, 0);
    worker.open('append');
    await turn();
    assert.equal(budget.usedBytes, 0, 'late worker activity cannot recreate released metadata');
});

test('disposal during an already-spilled write preserves owned windows and releases the index', async () => {
    const { api } = controlledApi();
    const budget = observedBudget(api, 200000);
    const worker = new GatedWorker();
    const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0, workerFactory: () => worker });
    await store.append(rows(100));
    worker.open('create');
    await turn();
    assert.equal(store.inMemory, false);
    const window = await store.readOwned(0, 10);
    const windowBytes = budget.usedBytes - metadataBytes([rows(100)]);
    worker.gates.add('append');
    await store.append(rows(231, 'urn:later:'));
    await turn();
    assert.equal(worker.waiting.length, 1);
    const beforeDisposal = budget.usedBytes;
    worker.gates.add('dispose');
    const disposing = store.dispose();
    await turn();
    assert.equal(budget.usedBytes, beforeDisposal - metadataBytes([rows(100)]),
        'the pending write keeps its captured source and metadata charged until the worker closes');
    worker.open('dispose');
    await disposing;
    await turn();
    assert.equal(budget.usedBytes, windowBytes, 'only the independent owned window survives disposal');
    assert.equal(window.rows[0][0].value, 'urn:row:0');
    worker.open('append');
    await turn();
    assert.equal(budget.usedBytes, windowBytes);
    window.release();
    window.release();
    assert.equal(budget.usedBytes, 0);
});

test('a failed stored truncate still releases discarded unwritten metadata before another append', async () => {
    const { api } = controlledApi();
    const budget = observedBudget(api, 200000);
    const worker = new FailingGatedWorker();
    const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0, workerFactory: () => worker });
    const initial = rows(100);
    const first = rows(50, 'urn:first:');
    const discarded = rows(25, 'urn:discarded:');
    try {
        await store.append(initial);
        worker.open('create');
        await turn();
        worker.gates.add('append');
        worker.gates.add('truncate');
        await store.append(first);
        await store.append(discarded);
        const truncating = store.truncate(50);
        const rejected = assert.rejects(truncating, /controlled storage failure/);
        await turn();
        worker.open('append');
        await turn();
        worker.fail('truncate');
        await rejected;
        assert.equal(await store.count(), 150, 'the failed disk truncate leaves its written prefix readable');
        assert.equal(budget.usedBytes, metadataBytes([initial, first]),
            'discarded unwritten rows cannot leave unused metadata charged after a failed disk truncate');
        const later = rows(13, 'urn:after-failure:');
        await store.append(later);
        await turn();
        await assertRows(store, initial.concat(first, later));
    } finally {
        await store.dispose();
        assert.equal(budget.usedBytes, 0);
    }
});

