test('many single-row admissions support bounded late windows and subsequent write-behind batches', async () => {
    const { api } = controlledApi();
    const budget = observedBudget(api, 8 * 1024 * 1024);
    const worker = new GatedWorker();
    const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0, workerFactory: () => worker });
    const expected = rows(10000);
    try {
        for (const row of expected) await store.append([row]);
        worker.open('create');
        await turn();
        assert.equal(store.inMemory, false);
        assert.equal(budget.usedBytes, expected.length * 176, 'every individual admitted backing array is accounted');
        for (const index of [0, 1, 4999, 5000, 9998, 9999]) {
            const window = await store.readOwned(index, 1);
            assert.equal(window.rows[0][0].value, expected[index][0].value);
            window.release();
        }
        const later = rows(1000, 'urn:write-behind:');
        for (const row of later) await store.append([row]);
        await turn();
        assert.equal(await store.count(), expected.length + later.length);
        assert.equal(budget.usedBytes, (expected.length + later.length) * 176);
        await store.truncate(9999);
        await store.append(rows(1, 'urn:replacement:'));
        await turn();
        const tail = await store.readOwned(9998, 2);
        assert.equal(tail.rows[0][0].value, 'urn:row:9998');
        assert.equal(tail.rows[1][0].value, 'urn:replacement:0');
        tail.release();
    } finally {
        await store.dispose();
        assert.equal(budget.usedBytes, 0);
    }
});

