test('unloading releases captured source rows even when the sent write is deliberately abandoned', async () => {
    const listeners = new Map();
    const { api } = controlledApi({ addEventListener(type, callback) {
        listeners.set(type, [...(listeners.get(type) || []), callback]);
    } });
    const budget = observedBudget(api, 200000);
    const worker = new GatedWorker();
    const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0, workerFactory: () => worker });
    await store.append(rows(100));
    worker.open('create');
    await turn();
    assert.equal(store.inMemory, false);
    worker.gates.add('append');
    await store.append(rows(231, 'urn:later:'));
    let outcome = 'pending';
    store.truncate(0).then(() => { outcome = 'resolved'; }, () => { outcome = 'rejected'; });
    await turn();
    assert.equal(worker.waiting.length, 1, 'the truncate waits for a sent write with no reply');
    for (const callback of listeners.get('pagehide') || []) callback({ type: 'pagehide', persisted: false });
    await store.dispose();
    await turn();
    assert.equal(worker.terminated, true);
    assert.equal(worker.received.some(message => message.op === 'dispose'), false, 'unload delegates disk cleanup');
    assert.equal(outcome, 'pending', 'accepted pending work leaves with the departing document');
    assert.equal(budget.usedBytes, 0, 'worker closure releases source and metadata without waiting for that work');
    worker.open('append');
    await turn();
    assert.equal(budget.usedBytes, 0);
});

function payloadRows(count, first = 0) {
    return Array.from({ length: count }, (_, index) => [{ kind: 'literal',
        value: String(first + index).padStart(6, '0') + 'x'.repeat(400) }]);
}

for (const alreadyStored of [false, true]) {
    const phase = alreadyStored ? 'stored write-behind' : 'initial catch-up';
    test(`${phase} splits coalesced records to fit temporary headroom`,
        async () => {
            const { api } = controlledApi();
            const budget = observedBudget(api, 2 * 1024 * 1024);
            const worker = new GatedWorker();
            const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0,
                workerFactory: () => worker });
            const blocker = budget.createReservation('retained');
            const initial = alreadyStored ? [rows(1, 'urn:initial:'), rows(1, 'urn:held:')] : [];
            const input = Array.from({ length: 4 }, (_, index) => payloadRows(250, index * 250));
            try {
                if (alreadyStored) {
                    await store.append(initial[0]);
                    worker.open('create');
                    await turn();
                    worker.gates.add('append');
                    await store.append(initial[1]);
                }
                for (const batch of input) await store.append(batch);
                await blocker.grow(budget.maxBytes / 2 - budget.retainedBytes);
                if (alreadyStored) worker.open('append');
                else worker.open('create');
                await turn();
                assert.equal(worker.rows.length, input.flat().length + initial.length,
                    'safe input records must finish writing without waiting for retained source memory');
                assert.equal(store.inMemory, false);
                const writes = worker.received.filter(message => message.op === 'append');
                assert.ok(writes.length >= (alreadyStored ? 4 : 2),
                    'coalescing respects a byte bound as well as row count');
                assert.ok(writes.every(message => message.text.length * 4 + message.rowCount * 16
                    <= budget.maxBytes / 2),
                    'every splittable transfer fits the protected temporary headroom');
                assert.equal(budget.usedBytes, blocker.bytes + metadataBytes(initial.concat(input)),
                    'partial source batches release exactly the bytes successfully written');
                blocker.release();
                await assertRows(store, initial.concat(input).flat());

                if (alreadyStored) {
                    const largeInput = payloadRows(1000, 1000);
                    const beforeWrites = worker.received.filter(message => message.op === 'append').length;
                    await store.append(largeInput);
                    await turn();
                    const newWrites = worker.received.filter(message => message.op === 'append').slice(beforeWrites);
                    assert.ok(newWrites.length > 1, 'one admitted input array can be split across several writes');
                    assert.ok(newWrites.every(message => message.text.length * 4 + message.rowCount * 16
                        <= budget.maxBytes / 2));
                    assert.equal(budget.usedBytes, metadataBytes(initial.concat(input, [largeInput])));
                    await assertRows(store, initial.concat(input, [largeInput]).flat());
                }
            } finally {
                blocker.release();
                await store.dispose();
                assert.equal(budget.usedBytes, 0);
            }
        });
}

test('stored writes waiting for temporary space cannot re-enter their own pressure handler', async () => {
    const { api } = controlledApi();
    const budget = observedBudget(api, 20000);
    const worker = new GatedWorker();
    const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0, workerFactory: () => worker });
    const blocker = budget.createReservation('temporary');
    try {
        await store.append(rows(1));
        worker.open('create');
        await turn();
        const later = rows(4, 'urn:later:');
        const admission = later.reduce((sum, row) => sum + api.estimateRowBytes(row), 0) + metadataBytes([later]);
        await blocker.grow(budget.maxBytes - budget.usedBytes - admission);
        await store.append(later);
        await turn();
        assert.equal(budget.requests.filter(request => request.category === 'temporary' && !request.settled).length, 1,
            'one pending drain owns one temporary request, even when grow synchronously invokes pressure handlers');
        blocker.release();
        await turn();
        assert.equal(worker.rows.length, 5);
        await assertRows(store, rows(1).concat(later));
    } finally {
        blocker.release();
        await store.dispose();
        assert.equal(budget.usedBytes, 0);
    }
});

for (const exceedsTotal of [false, true]) {
    const outcome = exceedsTotal ? 'retains the normal total-budget failure'
        : 'may exceed protected headroom when total space permits';
    test(`one indivisible row ${outcome}`,
        async () => {
            const { api } = controlledApi();
            const budget = observedBudget(api, 10000);
            const workers = [];
            const store = await api.createRowStore({ memoryBudget: budget, spillRowLimit: 0, workerFactory() {
                const worker = new MemoryWorker();
                workers.push(worker);
                return worker;
            } });
            const row = [{ kind: 'literal', value: 'x'.repeat(exceedsTotal ? 3000 : 1500) }];
            try {
                await store.append([row]);
                await turn();
                assert.equal(store.inMemory, exceedsTotal);
                assert.equal(await store.count(), 1);
                if (exceedsTotal) {
                    assert.equal(workers.length, 2, 'the normal retry policy still applies to an indivisible row');
                    assert.ok(workers.every(worker => !worker.messages.some(message => message.op === 'append')),
                        'a row above the total transfer budget is rejected before encoding or dispatch');
                    assert.equal((await store.read(0, 1))[0][0].value, row[0].value);
                } else {
                    assert.equal(workers.length, 1);
                    assert.deepEqual(workers[0].rows, [row], 'the chunker never discards or endlessly splits one row');
                    const write = workers[0].messages.find(message => message.op === 'append');
                    assert.ok(write.text.length * 4 + 16 > budget.maxBytes / 2);
                }
                await store.truncate(0);
                assert.equal(budget.usedBytes, 0);
            } finally {
                await store.dispose();
                assert.equal(budget.usedBytes, 0);
            }
        });
}
